447	#ifndef VSIMSAVABLE
448	  if (args.save_ctx || args.continue_ctx || args.context_dir != "./saved_ctx/")
449	  {
450	    spdlog::critical(
451	      "--save, --continue, and --context-dir require VSIMSAVABLE build");
