454	#endif
455	
456	  if (!args.resume_from_qemu.empty() && args.continue_ctx)
457	    throw std::runtime_error(
458	      "--resume-from-qemu and --continue are mutually exclusive");
459	
460	  print_version();
461	
462	  // systemc and cci init
463	  auto broker = cci_utils::broker{"global_broker"};
464	  cci::cci_register_broker(broker);
465	
466	  const auto time_resolution = sc_core::sc_get_time_resolution();
467	  spdlog::debug("Using time resolution: {}", time_resolution.to_string());
468	
469	  std::optional<MmapBacking> shared_ram;
470	  if (!args.shared_mem_path.empty()) {
471	    if (args.shared_mem_size == 0)
472	      throw std::runtime_error(
473	        "--shared-mem-path requires --shared-mem-size > 0");
474	    shared_ram.emplace(args.shared_mem_path, args.shared_mem_size);
475	  } else if (args.shared_mem_size != 0) {
476	    throw std::runtime_error(
477	      "--shared-mem-size requires --shared-mem-path");
478	  }
479	
480	  // Hybrid mode: the mmap window is the only RAM; QEMU virt has no alias.
481	  const MemoryRegion ram_region = shared_ram
482	    ? MemoryRegion{args.shared_mem_base,
483	                   args.shared_mem_base + args.shared_mem_size - 1}
484	    : MemoryRegion{RAM_BASE, RAM_END};
485	  const MemoryRegion ram_alias_region = shared_ram
486	    ? MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
487	                   SimpleMemory<32>::INVALID_ADDRESS}
488	    : MemoryRegion{RAM_ALIAS_BASE, RAM_ALIAS_END};
489	
490	  // run simulation
491	  const auto do_sim = [&]<typename CPU>() -> int {
492	    Simulator<CPU> sim{
493	      "sim",
494	      shared_ram ? shared_ram->span() : std::span<uint8_t>{},
495	      ram_region, ram_alias_region};
496	
497	    if (args.memmap) {
498	      sim.platform.interconnect.dump_region();
499	      return 0;
500	    }
501	
502	    sim.set_mem_latency(args.mem_latency);
503	
504	    if (!args.ilm_file.empty())
505	      sim.load_image(args.ilm_file, MEM_TYPE::ILM);
506	
507	    if (!args.dlm_file.empty())
508	      sim.load_image(args.dlm_file, MEM_TYPE::DLM);
509	
510	    // End of elaboration
511	    sc_core::sc_start(sc_core::SC_ZERO_TIME);
512	
513	    const auto t0 = std::chrono::steady_clock::now();
514	
515	    if (!args.waveform_file.empty())
516	      sim.enable_waveform(args.waveform_file);
517	
518	    if (!args.pc_trace_file.empty())
519	      sim.enable_pc_trace(args.pc_trace_file);
520	
521	    if (!args.kanata_file.empty() && !args.clarity_file.empty())
522	      throw std::runtime_error("--kanata and --clarity are mutually exclusive");
523	
524	    std::optional<kanata::LoopGate> loop_gate;
525	    if (args.kanata_loop_start.has_value()
526	        != args.kanata_loop_end.has_value())
527	      throw std::runtime_error(
528	        "--kanata-loop-start and --kanata-loop-end must be specified together");
529	    if (args.kanata_loop_start.has_value()) {
530	      if (args.kanata_file.empty() && args.clarity_file.empty())
531	        throw std::runtime_error(
532	          "--kanata-loop-* requires --kanata or --clarity");
533	      if (args.kanata_loop_record == 0)
534	        throw std::runtime_error("--kanata-loop-record must be >= 1");
535	      loop_gate = kanata::LoopGate{*args.kanata_loop_start,
536	                                   *args.kanata_loop_end,
537	                                   args.kanata_loop_skip,
538	                                   args.kanata_loop_record};
539	    }
540	
541	    // --kanata-roi defers kanata enable until after resume + handoff setup so
542	    // the gate can be auto-derived from the resumed PC + CsrTrigger / exit PC.
543	    if (args.kanata_roi) {
544	      if (args.kanata_file.empty())
545	        throw std::runtime_error("--kanata-roi requires --kanata <file>");
546	      if (loop_gate)
547	        throw std::runtime_error(
548	          "--kanata-roi and --kanata-loop-* are mutually exclusive");
549	      if (!args.clarity_file.empty())
550	        throw std::runtime_error("--kanata-roi is not supported with --clarity");
551	      if (args.hybrid_icount)
552	        throw std::runtime_error(
553	          "--kanata-roi is incompatible with --hybrid-icount "
554	          "(no single exit PC); use --mode csr or --mode pc instead");
555	      if (args.resume_from_qemu.empty())
556	        throw std::runtime_error(
557	          "--kanata-roi requires --resume-from-qemu");
558	    }
559	
560	    if (!args.kanata_file.empty() && !args.kanata_roi)
561	      sim.enable_kanata(args.kanata_file, args.objdump_file, loop_gate);
562	
563	    if (!args.clarity_file.empty())
564	      sim.enable_clarity(args.clarity_file, args.objdump_file, loop_gate);
565	
566	    // In tier-2 hybrid resume, QEMU 1 already loaded the ELF into the
567	    // shared mmap. Re-loading would `std::fill_n(memsz - filesz, 0)` over
568	    // each PT_LOAD's .bss tail, wiping phase-1 writes to static buffers.
569	    // Still parse the ELF to set the reset vector -- between sim.reset()
570	    // and apply_resume_from_qemu's DMI halt, the hart fetches one or two
571	    // instructions from the reset vector; if that address is unmapped
572	    // the bus errors leave the hart in a state the resume cannot recover.
573	    const bool elf_already_in_shared_mmap =
574	      !args.resume_from_qemu.empty() && !args.shared_mem_path.empty();
575	    if (!args.elf_file.empty() && !args.continue_ctx)
576	      sim.load_elf(args.elf_file, /*skip_memory_load=*/elf_already_in_shared_mmap);
577	
578	    // Apply per-hart reset vector overrides (after load_elf sets defaults)
579	    for (const auto& s: args.reset_vectors) {
580	      auto [hart, addr] = parse_reset_vector(s);
581	      if (hart) {
582	        sim.set_reset_vector(*hart, addr);
583	      } else {
584	        for (size_t i = 0; i < sim.platform.reset_vector.size(); ++i)
585	          sim.set_reset_vector(i, addr);
586	      }
587	    }
588	
589	    if (args.continue_ctx)
590	      spdlog::info("You're resuming program from the given context");
591	
592	    if (!args.jtag_port && args.elf_file.empty() && !args.continue_ctx
593	        && args.resume_from_qemu.empty())
594	      throw std::runtime_error(
595	        "Required arg : program, --jtag-port, or --resume-from-qemu");
596	
597	    if (args.continue_ctx || args.save_ctx) {
598	      std::string_view s = args.context_dir;
599	      if (std::filesystem::exists(s) && !std::filesystem::is_directory(s))
600	        throw std::runtime_error("Error: Path " + std::string{s}
601	                                 + " exists but is not a directory.");
602	      if (!std::filesystem::exists(s)) {
603	        try {
604	          std::filesystem::create_directories(s);
605	        } catch (const std::filesystem::filesystem_error& e) {
606	          throw std::runtime_error(std::string{"Failed to create directory: "}
607	                                   + e.what());
608	        }
609	      }
610	      sim.context_config = {args.save_ctx, args.continue_ctx, args.context_dir};
611	    }
612	
613	    sim.reset();
614	
615	    if (!args.resume_from_qemu.empty())
616	      sim.apply_resume_from_qemu(args.resume_from_qemu);
617	    else if (args.start_halted) {
618	      // -S: halt the hart at startup (QEMU `-S` semantics) so a debugger
619	      // attaches to a stopped core. The handoff legs above already halt via
620	      // resume. Unbuffer stdout too, so the guest's console output (UART and
621	      // HTIF putchar) is visible while the hart is halted at a breakpoint, not
622	      // only when vsim exits and the buffer drains -- scoped to -S; ordinary
623	      // runs keep block buffering (spdlog logs to stderr, so this only touches
624	      // the guest console).
625	      sim.halt_for_debug();
626	      std::setvbuf(stdout, nullptr, _IONBF, 0);
627	    }
628	
629	    // Expose the JTAG port. When -S halted the hart in-process this must come
630	    // AFTER the halt: the DTM and halt_for_debug()'s SystemCDmiBus both master
631	    // platform.dmi, so a debugger connecting before the halt completes would
632	    // collide (jtag_dtm asserts on an overlapping AHB txn). With the hart halted
633	    // and that bus gone, the DTM is the sole bus master for the session. Without
634	    // -S the port simply opens and the hart free-runs (the legacy behaviour).
635	    if (args.jtag_port)
636	      sim.init_debug_port(args.jtag_port.value());
637	
638	    if (args.hybrid_enter_pc)
639	      spdlog::warn("--hybrid-enter-pc=0x{:x} ignored: entry trigger is "
640	                   "QEMU's job (use plugin enter_pc= arg)",
641	                   *args.hybrid_enter_pc);
642	
643	    if (!args.handoff_out.empty()) {
644	      if (args.hybrid_icount && args.hybrid_exit_pc)
645	        throw std::runtime_error(
646	          "--hybrid-icount and --hybrid-exit-pc are mutually exclusive");
647	      if (args.hybrid_icount)
648	        sim.enable_hybrid_icount_handoff(args.handoff_out,
649	                                         *args.hybrid_icount,
650	                                         args.vsim_warmup_icount);
651	      else
652	        sim.enable_hybrid_handoff(args.elf_file, args.handoff_out,
653	                                  args.hybrid_exit_pc, args.vsim_warmup_icount);
654	    }
655	
656	    if (args.cosim_lockstep) {
657	      if (args.elf_file.empty())
658	        throw std::runtime_error("--cosim-lockstep requires a program ELF");
659	      if (!args.resume_from_qemu.empty() || !args.handoff_out.empty()
660	          || args.hybrid_icount || args.hybrid_cosim
661	          || !args.hybrid_cosim_at.empty())
662	        throw std::runtime_error(
663	          "--cosim-lockstep is exclusive with the hybrid handoff args "
664	          "(--resume-from-qemu/--handoff-out/--hybrid-*)");
665	      if (args.cosim_out.empty())
666	        throw std::runtime_error("--cosim-lockstep requires --cosim-out");
667	      sim.enable_cosim_lockstep(args.cosim_arm_pc, args.cosim_out,
668	                                args.cosim_max_records);
669	    } else if (!args.cosim_out.empty() || args.cosim_arm_pc
670	               || args.cosim_max_records != 0) {
671	      throw std::runtime_error(
672	        "--cosim-out/--cosim-arm-pc/--cosim-max-records require "
673	        "--cosim-lockstep");
674	    }
675	
676	    if (args.hybrid_cosim || !args.hybrid_cosim_at.empty()) {
677	      if (args.hybrid_cosim && !args.hybrid_cosim_at.empty())
678	        throw std::runtime_error(
679	          "--hybrid-cosim and --hybrid-cosim-at are mutually exclusive");
680	      if (args.handoff_out.empty())
681	        throw std::runtime_error("--hybrid-cosim requires --handoff-out");
682	      if (args.hybrid_icount)
683	        throw std::runtime_error(
684	          "--hybrid-cosim is incompatible with --hybrid-icount");
685	      if (args.resume_from_qemu.empty())
686	        throw std::runtime_error("--hybrid-cosim requires --resume-from-qemu");
687	      if (args.hybrid_cosim) {
688	        if (*args.hybrid_cosim == 0)
689	          throw std::runtime_error("--hybrid-cosim: interval must be >= 1");
690	        sim.enable_hybrid_cosim(*args.hybrid_cosim);
691	      } else {
692	        sim.enable_hybrid_cosim_targets(
693	          parse_cosim_targets(args.hybrid_cosim_at));
694	      }
695	    }
696	
697	    if (args.kanata_roi)
698	      sim.enable_kanata_roi(args.kanata_file, args.objdump_file,
699	                            args.hybrid_exit_pc);
700	
701	    const int exit_code = sim.run();
702	
703	    sim.cpu.final();
704	
705	    const auto t1 = std::chrono::steady_clock::now();
706	    const auto cycles = sim.get_cycles();
707	    spdlog::info("{} cycles simulated", cycles);
708	    if (cycles > 0) {
709	      const auto ms =
710	        std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0);
711	      spdlog::info("{}.{:03}s elapsed, {:.3f}Hz", ms.count() / 1000,
712	                   ms.count() % 1000,
713	                   double(cycles) / double(ms.count()) * 1000.0);
714	    }
715	    return exit_code;
716	  };
717	
718	  return do_sim.operator()<VSIM_CPU_INTERFACE_CLASS>();
719	
720	} catch (const std::exception& e) {
721	  spdlog::critical("fatal exception: {}\n", e.what());
722	  std::exit(EXIT_FAILURE);
723	} catch (...) {
724	  std::terminate();
725	}
