39	template<typename CPU>
40	class Simulator : sc_core::sc_module
41	{
42	  using PLATFORM = Platform<platform_config<CPU>>;
43	  static constexpr bool is_axi = (CPU::SYSTEM_BUS_TYPE == BusTypes::AXI);
44	  static constexpr auto bus_width = PLATFORM::data_width;
45	
46	  // Helper: create an AXI→TLM bridge, bind clock, connect initiator BFM
47	  auto make_axi_to_tlm(const char* name, auto& bfm_socket)
48	    -> std::unique_ptr<axi_to_tlm_bridge<bus_width>>
49	  {
50	    auto bridge = std::make_unique<axi_to_tlm_bridge<bus_width>>(name);
51	    bridge->pe.clk_i.bind(platform.clk);
52	    bfm_socket.bind(bridge->axi_tsck);
53	    return bridge;
54	  }
55	
56	  // Helper: create a TLM→AXI bridge, bind clock, connect target BFM
57	  auto make_tlm_to_axi(const char* name, auto& bfm_socket)
58	    -> std::unique_ptr<tlm_to_axi_bridge<bus_width>>
59	  {
60	    auto bridge = std::make_unique<tlm_to_axi_bridge<bus_width>>(name);
61	    bridge->pe.clk_i.bind(platform.clk);
62	    bridge->axi_isck.bind(bfm_socket);
63	    return bridge;
64	  }
65	
66	public:
67	  CPU cpu;
68	  PLATFORM platform;
69	
70	  // AXI bridges (only used when is_axi == true, null otherwise)
71	  std::unique_ptr<axi_to_tlm_bridge<bus_width>> mem_bridge;
72	  std::unique_ptr<axi_to_tlm_bridge<bus_width>> mmio_bridge;
73	  std::unique_ptr<tlm_to_axi_bridge<bus_width>> hvm_bridge;
74	  std::unique_ptr<tlm_to_axi_bridge<bus_width>> slv_bridge;
75	
76	  // sys bus (64-bit slave port on CPU, needs width adapter to 256-bit
77	  // interconnect)
78	  static constexpr std::size_t sys_bus_width = 64;
79	  std::unique_ptr<socket_width_adapter<bus_width, sys_bus_width>> sys_adapter;
80	  std::unique_ptr<tlm_to_axi_bridge<sys_bus_width>> sys_bridge;
81	
82	#if _NDS_IOCP_NUM > 0
83	  // iocp_master connects directly to CPU, not through the interconnect.
84	  // It needs to speak the CPU's bus protocol.
85	  using IocpInitiatorType = std::
86	    conditional_t<is_axi, AxiPeInitiator<bus_width>, AhbPeInitiator<bus_width>>;
87	  IocpInitiatorType iocp_master;
