90	private:
91	  // debug
92	  jtag_dtm& dtm;
93	  bool dtm_debug = false;
94	  TraceController<CPU> trace_;
95	
96	  // Hybrid handoff (vsim->QEMU). Order matters: dmi_bus_ is referenced by
97	  // handoff_, so it must be declared first.
98	  std::unique_ptr<hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
99	                                        PLATFORM::dmi_data_width>>
100	    hybrid_dmi_bus_;
101	  std::optional<hybrid::HandoffController<hybrid::CsrTrigger,
102	                                          hybrid::MeasureStartSnapshot>>
103	    hybrid_handoff_;
104	  std::optional<hybrid::HandoffController<hybrid::IcountTrigger,
105	                                          hybrid::MeasureStartSnapshot>>
106	    hybrid_icount_handoff_;
107	  std::string hybrid_state_path_;
108	  std::optional<hybrid_state_v1> hybrid_input_state_;
109	  // cosim_redesign F4: lock-step session config (set => run() runs the
110	  // DMI-driven step loop instead of the main cycle loop).
111	  std::optional<hybrid::LockstepSession::Config> lockstep_cfg_;
112	  std::string lockstep_out_;
113	  uint64_t elf_entry_ = 0;
114	
115	  using xlen_t = std::conditional_t<CPU::NDS_XLEN <= 32, uint32_t, uint64_t>;
116	
117	public:
118	  ContextManager<CPU> context_config;
119	
120	  Simulator(const sc_core::sc_module_name& name,
121	            std::span<uint8_t> ram_buffer = {},
122	            MemoryRegion ram_region = {RAM_BASE, RAM_END},
123	            MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
124	      : sc_core::sc_module{name},
125	        platform("platform", ram_buffer, ram_region, ram_alias_region),
126	        dtm(platform.dtm)
127	  {
128	    cpu.bind(platform.clk, platform.resetn, platform.reset_vector,
129	             platform.dmi_signals, platform.wfi_signal, platform.int_trigger);
130	
131	    // --- CPU memory BFM → interconnect ---
132	    if constexpr (is_axi) {
133	      mem_bridge = make_axi_to_tlm("mem_bridge", cpu.mem_bfm.isckt);
134	      platform.interconnect.bind_initiator(mem_bridge->tlm_isck);
135	    } else {
136	      platform.interconnect.bind_initiator(cpu.mem_bfm.isckt);
137	    }
138	
139	    // --- CPU MMIO BFM → interconnect ---
140	    if constexpr (requires { cpu.mmio_bfm; }) {
141	      if constexpr (is_axi) {
142	        mmio_bridge = make_axi_to_tlm("mmio_bridge", cpu.mmio_bfm.isckt);
143	        platform.interconnect.bind_initiator(mmio_bridge->tlm_isck);
144	      } else {
145	        platform.interconnect.bind_initiator(cpu.mmio_bfm.isckt);
146	      }
147	    }
148	
149	    // --- CPU HVM subordinate port ---
150	    if constexpr (requires { cpu.hvm_bfm; }) {
151	      if constexpr (is_axi) {
152	        hvm_bridge = make_tlm_to_axi("hvm_bridge", cpu.hvm_bfm.tsckt);
153	        platform.interconnect.bind_target(
154	          hvm_bridge->tlm_tsck,
155	          {CPU::NDS_HVM_BASE,
156	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
157	      } else {
158	        platform.interconnect.bind_target(
159	          cpu.hvm_bfm.tsckt,
160	          {CPU::NDS_HVM_BASE,
161	           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
162	      }
163	      platform.custom_master.hvm_base = CPU::NDS_HVM_BASE;
164	    }
165	
166	    // --- CPU slave port ---
167	    if constexpr (requires { cpu.slv_bfm; }) {
168	      if constexpr (is_axi) {
169	        slv_bridge = make_tlm_to_axi("slv_bridge", cpu.slv_bfm.tsckt);
170	        platform.interconnect.bind_target(slv_bridge->tlm_tsck,
171	                                          {HART0_ILM_BASE, HART0_DLM_END});
172	      } else {
173	        platform.interconnect.bind_target(cpu.slv_bfm.tsckt,
174	                                          {HART0_ILM_BASE, HART0_DLM_END});
175	      }
176	      platform.custom_master.ilm_base = HART0_ILM_BASE;
177	      platform.custom_master.dlm_base = HART0_DLM_BASE;
178	    }
179	
180	    // --- CPU sys bus (slave port, 64-bit) → interconnect ---
181	    if constexpr (requires { cpu.sys_bfm; }) {
182	      sys_adapter =
183	        std::make_unique<socket_width_adapter<bus_width, sys_bus_width>>(
184	          "sys_adapter");
185	      sys_bridge =
186	        std::make_unique<tlm_to_axi_bridge<sys_bus_width>>("sys_bridge");
187	      sys_bridge->pe.clk_i.bind(platform.clk);
188	      sys_bridge->axi_isck.bind(cpu.sys_bfm.tsckt);
189	      sys_adapter->isck.bind(sys_bridge->tlm_tsck);
190	      platform.interconnect.bind_target(sys_adapter->tsck,
191	                                        {MLIF_BASE, SLIF_END});
192	    }
193	
194	#if _NDS_IOCP_NUM > 0
195	    iocp_master.protocol_engine.clk_i.bind(platform.clk);
196	    iocp_master.socket.bind(cpu.iocp_bfm.tsckt);
197	#endif // _NDS_IOCP_NUM
198	  }
