209	  // Caller invariant: the CPU must already be out of reset.
210	  void apply_resume_from_qemu(const std::string& path)
211	  {
212	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
213	      bus{platform.dmi, platform.clk.period()};
214	    hybrid_input_state_ = hybrid::load_state(path);
215	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
216	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
217	    // this region to repopulate v0..v31, so the bytes must be in place first.
218	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
219	    // dropping V state.
220	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
221	      hybrid::stage_v_to_scratch(*hybrid_input_state_,
222	                                 platform.main_memory.data);
223	    }
224	    hybrid::ResumeDriver driver(bus, v_scratch_gpa());
225	    driver.resume(*hybrid_input_state_);
226	  }
227	
228	  // -S: halt the hart in-process BEFORE the main loop runs it, mirroring QEMU's
229	  // `-S`. Without it the loop free-runs the hart, and a debugger that attaches
230	  // over --jtag-port cannot catch a running hart on the bitbang DTM -- its
231	  // dmstatus never reaches `allhalted` (the hart oscillates
232	  // unavailable/havereset/running). Uses the same in-process DMI halt the hybrid
233	  // handoff relies on (ResumeDriver::halt over SystemCDmiBus, which drains every
234	  // access to completion -- unlike the passive, main-loop-clocked DTM). The
235	  // debugger then attaches to an already-stopped hart and its `continue`
236	  // (resumereq) starts execution; the hart fetches one or two crt0 instructions
237	  // before haltreq takes effect, exactly as the resume path does.
238	  void halt_for_debug()
239	  {
240	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
241	      bus{platform.dmi, platform.clk.period()};
242	    hybrid::ResumeDriver{bus}.halt();
243	    spdlog::info("hart halted at startup (-S); resume with the debugger's "
244	                 "`continue`");
245	  }
246	
247	  // Builds the DMI bus + warmup snapshot shared by both handoff modes:
248	  // stores the bus in hybrid_dmi_bus_ and returns the snapshot for the caller
249	  // to move into its controller.
250	  auto make_handoff_snapshot(uint64_t vsim_warmup_icount)
251	    -> hybrid::MeasureStartSnapshot
252	  {
253	    hybrid_dmi_bus_ = std::make_unique<
254	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
255	                            PLATFORM::dmi_data_width>>(platform.dmi,
256	                                                       platform.clk.period());
257	    if (vsim_warmup_icount > 0)
258	      spdlog::info("hybrid: warmup window enabled, K={}", vsim_warmup_icount);
259	    return hybrid::MeasureStartSnapshot{vsim_warmup_icount, *hybrid_dmi_bus_};
260	  }
261	
262	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
263	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
264	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
265	  //
266	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
267	  // mode) and the ELF scan is skipped: the binary need not contain a magic
268	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
269	  // run -- callers pass exactly one form.
270	  void enable_hybrid_handoff(const std::string& elf_path,
271	                             const std::string& state_out_path,
272	                             std::optional<uint64_t> exit_pc = std::nullopt,
273	                             uint64_t vsim_warmup_icount = 0)
274	  {
275	    hybrid::CsrTrigger trigger;
276	    if (exit_pc) {
277	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
278	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
279	    } else {
280	      auto elf = LIEF::ELF::Parser::parse(elf_path);
281	      if (!elf)
282	        throw std::runtime_error(
283	          "enable_hybrid_handoff: failed to parse " + elf_path);
284	      for (const auto& seg: elf->segments()) {
285	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
286	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
287	        const auto content = seg.content();
288	        const std::span<const uint8_t> bytes{content.data(), content.size()};
289	        trigger.scan_buffer(bytes, seg.virtual_address());
290	      }
291	    }
292	
293	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
294	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
295	                            std::move(snapshot), v_scratch_gpa());
296	    if (hybrid_input_state_)
297	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
298	    hybrid_state_path_ = state_out_path;
299	  }
300	
301	  // icount-trigger variant: drain after `target` committed insns retire,
302	  // regardless of PC. Sibling to enable_hybrid_handoff (which is CSR/PC). The
303	  // two modes are mutually exclusive on a single run -- callers pass at most
304	  // one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
305	  void enable_hybrid_icount_handoff(const std::string& state_out_path,
306	                                    uint64_t icount_target,
307	                                    uint64_t vsim_warmup_icount = 0)
308	  {
309	    hybrid::IcountTrigger trigger{icount_target};
310	    spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);
311	
312	    auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
313	    hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
314	                                   std::move(snapshot), v_scratch_gpa());
315	    if (hybrid_input_state_)
316	      hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
317	    hybrid_state_path_ = state_out_path;
318	  }
319	
320	  // cosim_roi F2 / cosim_redesign F3: drain resumable checkpoints -- every
321	  // `interval` retires, or at each explicit retire target (the last target
322	  // finishes the run). Records append to the `<handoff_out>.ckpts` stream
323	  // (concatenated hybrid_state_v1; count = filesize / sizeof). Call AFTER
324	  // enable_hybrid_handoff -- checkpoints ride the CSR/PC handoff
325	  // controller, so icount mode cannot carry them.
326	  void enable_hybrid_cosim(uint64_t interval)
327	  {
328	    spdlog::info("hybrid cosim: checkpoint every {} retires", interval);
329	    require_handoff_for_cosim();
330	    hybrid_handoff_->enable_cosim(interval, make_cosim_stream_sink());
331	  }
332	
333	  void enable_hybrid_cosim_targets(std::vector<uint64_t> targets)
334	  {
335	    spdlog::info("hybrid cosim: {} explicit checkpoint targets, finish at "
336	                 "retire {}", targets.size(), targets.back());
337	    require_handoff_for_cosim();
338	    hybrid_handoff_->enable_cosim_targets(std::move(targets),
339	                                          make_cosim_stream_sink());
340	  }
341	
342	  // cosim_redesign F4: lock-step DV mode. Boot the ELF, halt at reset,
343	  // single-step to `arm_pc` (default: the ELF entry), then drain one full
344	  // record per execution attempt into the `out_path` stream. K=0 runs
345	  // until the program exits (SimControl).
346	  void enable_cosim_lockstep(std::optional<uint64_t> arm_pc,
347	                             const std::string& out_path,
348	                             uint64_t max_records)
349	  {
350	    hybrid_dmi_bus_ = std::make_unique<
351	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
352	                            PLATFORM::dmi_data_width>>(platform.dmi,
353	                                                       platform.clk.period());
354	    lockstep_cfg_ = hybrid::LockstepSession::Config{
355	      .arm_pc      = arm_pc.value_or(elf_entry_),
356	      .max_records = max_records,
357	    };
358	    lockstep_out_ = out_path;
359	    spdlog::info("cosim lockstep: arm pc=0x{:x}, max records={}, out={}",
360	                 lockstep_cfg_->arm_pc, max_records, out_path);
361	  }
