363	private:
364	  // L26: the GUEST address of the V-register transport page -- the top page of
365	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
366	  // so this sits just past the program's declared RAM and never collides with
367	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
368	  auto v_scratch_gpa() const -> uint64_t
369	  {
370	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
371	                                 platform.main_memory.data.size());
372	  }
373	
374	  void require_handoff_for_cosim()
375	  {
376	    if (!hybrid_handoff_)
377	      throw std::runtime_error(
378	        "enable_hybrid_cosim: requires the CSR/PC hybrid handoff "
379	        "(incompatible with --hybrid-icount)");
380	  }
381	
382	  // Record sink: V-merge from scratch RAM (same as the exit drain), then
383	  // append the record to the `path` stream. The stream is truncated here
384	  // so a re-run never carries stale records.
385	  auto make_stream_sink(const std::string& path)
386	    -> std::function<void(const hybrid_state_v1&, uint64_t)>
387	  {
388	    std::ofstream{path, std::ios::binary | std::ios::trunc};
389	    return [this, path](const hybrid_state_v1& drained, uint64_t k) {
390	      auto state = drained;
391	      if ((state.flags & HYBRID_FLAG_V) != 0u) {
392	        hybrid::read_v_from_scratch(
393	          state,
394	          std::span<const uint8_t>{platform.main_memory.data.data(),
395	                                   platform.main_memory.data.size()});
396	      }
397	      spdlog::info("hybrid cosim: record {} at pc=0x{:x}, appending to {}",
398	                   k, state.pc, path);
399	      std::ofstream f(path, std::ios::binary | std::ios::app);
400	      f.write(reinterpret_cast<const char*>(&state), sizeof(state));
401	    };
402	  }
403	
404	  auto make_cosim_stream_sink()
405	    -> std::function<void(const hybrid_state_v1&, uint64_t)>
406	  {
407	    return make_stream_sink(hybrid_state_path_ + ".ckpts");
408	  }
409	
410	  // The lock-step session replaces the main run loop entirely: every cycle
411	  // advance happens inside the DMI bus pumping. Device side effects (UART,
412	  // SimControl) still run; the stop check ends the session when the
413	  // program exits before max_records.
414	  auto run_lockstep_session() -> int
415	  {
416	    hybrid::LockstepSession session(
417	      *hybrid_dmi_bus_, *lockstep_cfg_, make_stream_sink(lockstep_out_),
418	      [this] {
419	        return platform.sim_control.exits >= 0
420	            || this->cpu.contextp()->gotFinish();
421	      },
422	      v_scratch_gpa());
423	    const uint64_t records = session.run();
424	    spdlog::info("cosim lockstep: {} record(s) written to {}", records,
425	                 lockstep_out_);
426	    return 0;
427	  }
