443	  // skip_memory_load: parse the ELF and set the reset vector, but leave
444	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
445	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
446	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
447	  // to static buffers. The reset vector is still set so the hart has a
448	  // valid fetch target during the post-reset cycles that precede the DMI
449	  // halt+DPC-write resume sequence.
450	  void load_elf(const std::string& path, bool skip_memory_load = false)
451	  {
452	    const auto elf = LIEF::ELF::Parser::parse(path);
453	    if (!elf) {
454	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
455	      exit(1);
456	    }
457	
458	    if (!skip_memory_load)
459	      read_elf_into_memory(
460	        *elf,
461	        static_cast<xlen_t>(platform.main_memory.region.base_address),
462	        platform.main_memory.data);
463	    for (auto& rv: platform.reset_vector)
464	      rv.write(elf->entrypoint());
465	    elf_entry_ = elf->entrypoint();
466	  }
467	
468	  void set_reset_vector(size_t hart, uint64_t addr)
469	  {
470	    if (hart >= platform.reset_vector.size()) {
471	      spdlog::critical("hart {} out of range (max {})", hart,
472	                       platform.reset_vector.size() - 1);
473	      std::exit(EXIT_FAILURE);
474	    }
475	    platform.reset_vector[hart].write(addr);
476	  }
477	
478	  void load_image(const std::string& path, MEM_TYPE type)
479	  {
480	    switch (type) {
481	    case MEM_TYPE::ILM:
482	      if constexpr (requires { cpu.set_ilm({}); }) {
483	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
484	      } else {
485	        throw std::runtime_error(
486	          "CPU does not support ILM - cannot load ILM ROM image");
487	      }
488	      break;
489	
490	    case MEM_TYPE::DLM:
491	      if constexpr (requires { cpu.set_dlm({}); }) {
492	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
493	      } else {
494	        throw std::runtime_error(
495	          "CPU does not support DLM - cannot load DLM ROM image");
496	      }
497	      break;
498	
499	    case MEM_TYPE::RAM:
500	      read_binary_file(path, [this](const auto& data) {
501	        if (data.size() > platform.main_memory.data.size())
502	          throw std::runtime_error("RAM image size exceeds main memory size");
503	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
504	      });
505	      break;
506	
507	    default:
508	      throw std::runtime_error("Unknown memory type");
509	    }
510	  }
511	
512	  void reset()
513	  {
514	    static constexpr int core_num = CPU::NDS_NHART;
515	    static constexpr int reset_val = (1 << core_num) - 1;
516	
517	    platform.resetn.write(0);
518	    auto saved = context_config;
519	    context_config = {};
520	    this->run(1);
521	    context_config = saved;
522	
523	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
524	      spdlog::info("hart {} reset vector: {:#x}", i,
525	                   (uint64_t) platform.reset_vector[i].read());
526	
527	    platform.resetn.write(reset_val);
528	
529	    if (context_config.continue_from)
530	      restore_context(context_config.dir);
531	  }
532	
533	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
534	  {
535	    auto sa = memzeroed<struct sigaction>();
536	    sa.sa_handler = sigint_handler;
537	    sigemptyset(&sa.sa_mask);
538	
539	    auto oact = memzeroed<struct sigaction>();
540	    if (sigaction(SIGINT, &sa, &oact) == -1)
541	      perror("sigaction");
542	
543	    const auto restore_sigint = std::experimental::scope_exit{[&] {
544	      if (sigaction(SIGINT, &oact, nullptr) == -1)
545	        perror("sigaction");
546	    }};
547	
548	    // wait for debugger connections
549	    while (dtm_debug && !dtm.is_connected()) {
550	      dtm.try_accept_socket();
551	      if (ctrlc != 0) {
552	        return 130;
553	      }
554	      sleep(1);
555	    }
556	
557	    // cosim_redesign F4: the lock-step session owns all cycle advancement
558	    // (DMI pumping); the main loop below never runs.
559	    if (lockstep_cfg_) return run_lockstep_session();
560	
561	    [[maybe_unused]]
562	    bool ctx_resuming = context_config.continue_from;
563	    [[maybe_unused]]
564	    bool ctx_triggered = false;
565	
566	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
567	
568	      if (ctx_resuming) [[unlikely]] {
569	        // Pull up PLIC interrupt signal at the first cycle of the resume
570	        platform.int_trigger.write(1);
571	        ctx_resuming = false;
572	        ctx_triggered = true;
573	      }
574	
575	      sc_core::sc_start(platform.clk.period());
576	
577	      trace_.on_cycle(cpu);
578	
579	      if (hybrid_handoff_ || hybrid_icount_handoff_) [[unlikely]] {
580	        if (auto code = check_hybrid_handoff(); code) return *code;
581	      }
582	
583	      if (trace_.pipeview_wants_exit()) {
584	        spdlog::info("Pipeline viewer requested exit (Kanata loop window complete)");
585	        return 0;
586	      }
587	
588	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
589	        [[unlikely]]
590	      {
591	        context_config.save(platform, cpu);
592	        spdlog::info("User save context");
593	        return 0;
594	      }
595	
596	      if (ctrlc != 0) {
597	        ctrlc = 0;
598	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
599	        trace_.log_committed_pcs(cpu);
600	        return 130;
601	      }
602	
603	      if (ctx_triggered) [[unlikely]] {
604	        // Pull down the interrupt signal after 1 cycle
605	        platform.int_trigger.write(0);
606	        ctx_triggered = false;
607	      }
608	
609	      if (platform.sim_control.exits >= 0) {
610	        spdlog::info("sim_control: got exit {}, stopping",
611	                     platform.sim_control.exits);
612	        spdlog::info("Exit PC: {:x}", get_current_pc());
613	        trace_.log_committed_pcs(cpu);
614	        return platform.sim_control.exits;
615	      }
616	
617	      if (this->cpu.contextp()->gotFinish())
618	        return 0;
619	
620	      spdlog::trace("PC: {:x}", get_current_pc());
621	    }
622	    return 0;
623	  }
624	
625	  uint64_t get_current_pc()
626	  {
627	    if constexpr (requires { cpu.get_current_pc(); }) {
628	      return cpu.get_current_pc();
629	    }
630	    return std::numeric_limits<uint64_t>::max();
631	  }
632	
633	  auto check_hybrid_handoff() -> std::optional<int>
634	  {
635	    if constexpr (!requires { cpu.get_committed_pc(); }) {
636	      return std::nullopt;
637	    } else {
638	      const auto committed = cpu.get_committed_pc();
639	      if (committed.empty()) return std::nullopt;
640	      for (const auto pc: committed[0]) {
641	        auto state = std::optional<hybrid_state_v1>{};
642	        if (hybrid_handoff_)
643	          state = hybrid_handoff_->on_retire(pc);
644	        else if (hybrid_icount_handoff_)
645	          state = hybrid_icount_handoff_->on_retire(pc);
646	        if (state) {
647	          // V-register merge: the fixture's vsim-phase epilogue is expected
648	          // to have run vse8.v v0..v31 to scratch RAM before the exit
649	          // trigger fired. Read those bytes back into state.vreg[] so the
650	          // drained handoff state carries vsim's actual V values, not
651	          // QEMU 1's stale snapshot.
652	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
653	            hybrid::read_v_from_scratch(
654	              *state,
655	              std::span<const uint8_t>{platform.main_memory.data.data(),
656	                                       platform.main_memory.data.size()});
657	          }
658	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
659	                       pc, hybrid_state_path_);
660	          std::ofstream f(hybrid_state_path_, std::ios::binary);
661	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
662	          return hybrid::kExitHandoffToQemu;
663	        }
664	      }
665	      return std::nullopt;
666	    }
667	  }
668	
