    return 0;
  }

  if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
    [[unlikely]]
  {
    context_config.save(platform, cpu);
    spdlog::info("User save context");
    return 0;
  }

  if (ctrlc != 0) {
    ctrlc = 0;
    spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
    trace_.log_committed_pcs(cpu);
    return 130;
  }

  if (ctx_triggered) [[unlikely]] {
    // Pull down the interrupt signal after 1 cycle
    platform.int_trigger.write(0);
    ctx_triggered = false;
  }

  if (platform.sim_control.exits >= 0) {
    spdlog::info("sim_control: got exit {}, stopping",
                 platform.sim_control.exits);
    spdlog::info("Exit PC: {:x}", get_current_pc());
    trace_.log_committed_pcs(cpu);
    return platform.sim_control.exits;
  }

  if (this->cpu.contextp()->gotFinish())
    return 0;

  spdlog::trace("PC: {:x}", get_current_pc());
}
```

**Key points:**
- **Clock advance:** `sc_core::sc_start(platform.clk.period())` (line 575) steps the SystemC simulation by one clock period
- **CPU evaluation:** The Verilated model evaluates internally during `sc_start()`
- **Post-cycle checks:** After each cycle, checks for exit conditions (sim_control, hybrid handoff triggers, Ctrl+C, WFI, Kanata ROI window completion)
- **No explicit eval() call:** The Verilator model's evaluation is triggered by SystemC's built-in elaboration and time stepping

---

### 4. How Options Flow from argv to Simulation Core

**Flow Path:**

1. **Parse phase (main.cpp:264-444):**
   - `parser` class dispatches argv values into the local `args` struct
   - Each option's lambda captures `args` by reference (`[&]`)
   - Parsed values stored in `args` members (e.g., `args.mem_latency`, `args.hybrid_icount`, `args.cosim_lockstep`)

2. **Transfer to Simulator (main.cpp:491-502):**
   - `Simulator<CPU>` instance created (line 492-495)
   - Constructor takes generic initialization parameters
   - After construction, call individual setter methods:
     ```cpp
     sim.set_mem_latency(args.mem_latency);         // line 502
     sim.load_image(args.ilm_file, ...);            // line 505
     sim.load_image(args.dlm_file, ...);            // line 508
     sim.enable_waveform(args.waveform_file);       // line 516
     sim.enable_pc_trace(args.pc_trace_file);       // line 519
     sim.enable_kanata(...);                        // line 561
     sim.apply_resume_from_qemu(...);               // line 616
     sim.init_debug_port(args.jtag_port.value());   // line 636
     sim.enable_hybrid_handoff(...);                // line 652
     sim.enable_cosim_lockstep(...);                // line 667
     ```

3. **Storage in Simulator members:**
   - Options that affect the simulation loop are stored in Simulator members or passed through to the Platform
   - Example: `mem_latency` (option) → `sim.set_mem_latency()` → `platform.main_memory.latency` field (in SimpleMemory)
   - Hybrid handoff options → stored in `hybrid_handoff_` and `hybrid_icount_handoff_` optional members (lines 101-106)
   - Lockstep config → stored in `lockstep_cfg_` optional member (line 111)

4. **Runtime access in cycle loop:**
   - The loop checks conditions like `if (hybrid_handoff_ || hybrid_icount_handoff_)` (line 579)
   - Memory latency is returned by `SimpleMemory::handle_trans()` from the `latency` field (used for TLM delay calculations)

**No global config struct** — vsim uses per-option setter methods and instance members, making the architecture modular and testable.

---

### To Add a New Option:

1. Add a member to the `args` struct (line 265-303 in main.cpp)
2. Register a parser handler (lines 310-442)
3. Create a setter/enable method on `Simulator<CPU>` (in simulator.hpp)
4. Call the setter after simulator instantiation (after line 502 in main.cpp)
5. Store the option value in a Simulator member if it needs to persist across the run loop
